 function mlsCure(x,reply){if(!x||(x.rule!=='K-ML'&&x.rule!=='K-SU'))return null; /* pkgMLS (ASK 351): TRIAL, list only; no status here starts with "retracted", so this rule accepts no withdrawal */
 const fd=s=>' '+String(s==null?'':s).replace(/\[[^\]]*:[^\]]*\]/g,' ').toLowerCase().replace(/n['’]t\b/g,' not').replace(/\bcannot\b/g,'can not').replace(/[^a-z ]/g,' ').replace(/\s+/g,' ').trim()+' ';
 const id=String(x.pair||'');if(!id)return {st:'UNCURED',why:'TRIAL rule (recorded and answered; it removes no seat; list only): no link named',line:null};const rx=new RegExp('\\b'+id.replace(/\s+vs\s+/,'\\s+vs\\.?\\s+')+'\\b','i');
 const mine=String(reply||'').split('\n').map(l=>l.replace(/[*_`]+/g,'').trim()).filter(l=>rx.test(l));const WD=/\b(?:RETRACTED|WITHDRAW(?:N|S)?|WITHDREW)\b/i;const add=(x.add||[]).map(p=>'"'+p+'"').join(', ');
 const wd=mine.find(l=>WD.test(l));if(wd)return {st:'CURED',why:'TRIAL rule ('+x.rule+', list only): the reply withdraws its line on '+id+'; recorded only',line:wd.slice(0,1500)};
 if(x.rule==='K-ML'){const ok=mine.find(l=>/\bMEANS\b/i.test(l)&&!(x.add||[]).some(p=>fd(l).includes(' '+p+' ')));if(ok)return {st:'CURED',why:'TRIAL rule (K-ML, list only): the reply writes '+id+' again without '+add+'; recorded only',line:ok.slice(0,1500)};}
 else{const ok=mine.find(l=>{if((x.oref||[]).some(r=>l.includes(r)))return true;const F=fd(l);return (x.otext||[]).some(t=>{const w=fd(t).trim().split(' ');for(let i=0;i+6<=w.length;i++)if(F.includes(' '+w.slice(i,i+6).join(' ')+' '))return true;return false;});});
  if(ok)return {st:'CURED',why:'TRIAL rule (K-SU, list only): the reply grades '+id+' on the whole sentence '+x.ref+'; recorded only',line:ok.slice(0,1500)};}
 return {st:'UNCURED',why:'TRIAL rule (recorded and answered; it removes no seat; list only): the reply '+(mine.length?'writes '+id+' but does not ':'writes no line on '+id+' that does not ')+(x.rule==='K-ML'?'drop '+add+' or withdraw the line':'grade it on the whole sentence '+x.ref+' or withdraw the line'),line:null};}
